#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    int current_floor = 0; // elevator starts at floor 0
    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long target = strtol(argv[i], &endptr, 10);
        /* The original program treats any negative value or any value greater than 9 as invalid.
           Non‑numeric strings are converted to 0 by strtol, which is a valid floor, matching the
           observed behaviour. */
        if (target < 0 || target > 9) {
            puts("INVALID_FLOOR");
            continue; // move on to the next argument
        }
        /* Move the elevator step by step, printing each movement. */
        while (current_floor < target) {
            printf("MOVE_UP %d->%d\n", current_floor, current_floor + 1);
            ++current_floor;
        }
        while (current_floor > target) {
            printf("MOVE_DOWN %d->%d\n", current_floor, current_floor - 1);
            --current_floor;
        }
        /* Arrival actions */
        printf("ARRIVE %d\n", current_floor);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current_floor);
    return 0;
}
